<?php
namespace App\Http\Controllers;
use App\Models\AdminAuditLog; use App\Models\Gig; use App\Models\Order; use App\Models\User; use Illuminate\Http\Request;
class AdminController extends Controller { public function index(){return view('admin.dashboard',['pendingGigs'=>Gig::with(['seller.profile','category'])->where('status','PENDING')->latest()->get(),'users'=>User::latest()->limit(20)->get(),'orders'=>Order::with('gig')->latest()->limit(20)->get()]);} public function approveGig(Gig $gig){$before=$gig->toArray();$gig->update(['status'=>'ACTIVE','published_at'=>now()]);AdminAuditLog::create(['admin_id'=>auth()->id(),'action'=>'approve_gig','target_type'=>'Gig','target_id'=>$gig->id,'before'=>$before,'after'=>$gig->fresh()->toArray(),'ip_address'=>request()->ip(),'user_agent'=>request()->userAgent()]);return back()->with('success','Gig approved.');} public function rejectGig(Request $r,Gig $gig){$gig->update(['status'=>'REJECTED']);return back()->with('success','Gig rejected.');} }
